const question = $json.question || "";
const sessionId = $json.sessionId || "default-session";
const specialistResults = $json.specialistResults || [];

const compactResults = specialistResults.map((result) => {
  return {
    agent: result.agent || "unknown_agent",
    domain: result.domain || "",
    answer: result.answer || "",
    keyFindings: result.keyFindings || [],
    recommendations: result.recommendations || [],
    confidence: result.confidence || "unknown",
    evidenceSummary: result.evidence
      ? Object.fromEntries(
          Object.entries(result.evidence).map(([key, value]) => [
            key,
            Array.isArray(value) ? `${value.length} records` : "available",
          ])
        )
      : {},
  };
});

const allRecommendations = [];
const allFindings = [];

for (const result of specialistResults) {
  if (Array.isArray(result.recommendations)) {
    allRecommendations.push(...result.recommendations);
  }
  if (Array.isArray(result.keyFindings)) {
    allFindings.push(...result.keyFindings);
  }
}

const systemPrompt = `
You are the Supply Chain Manager Agent.

Your job:
- Combine specialist agent outputs into one clear executive answer.
- Prioritize business impact.
- Identify risks, bottlenecks, supplier issues, logistics issues, sustainability concerns, and quality concerns.
- Give practical next actions.
- Do not invent facts.
- If specialist evidence is limited, clearly say that.
- Return ONLY valid JSON.

Important output rules:
For evidenceGraph.nodes, every node must include:
- id: string
- name: string
- type: string
- properties: object

For evidenceGraph.edges, every edge must include:
- id: string
- source: string
- target: string
- type: string
- properties: object

Strict supplier classification rules:
- Do not treat every Actor as a supplier.
- Supplier means actor_role is "supplier" or "manufacturer", or the evidence includes a SUPPLIES relationship.
- Recycling, waste, maintenance, testing, logistics, and person actors are not suppliers unless explicitly shown as suppliers.
- If evidence contains Recycling Facility P or Waste Disposal Provider Q, describe them as recycling/waste service actors, not suppliers.
- Use exact graph names. Do not rename or generalize entities.
`;

const userPrompt = `
User question:
${question}

Specialist agent results:
${JSON.stringify(compactResults, null, 2)}

All key findings:
${JSON.stringify(allFindings, null, 2)}

All recommendations:
${JSON.stringify(allRecommendations, null, 2)}

Return JSON with this exact schema:
{
  "answer": "string",
  "executiveSummary": "string",
  "specialistSummary": [
    {
      "agent": "string",
      "contribution": "string",
      "confidence": "low | medium | high | unknown"
    }
  ],
  "keyFindings": ["string"],
  "riskLevel": "low | medium | high | unknown",
  "recommendations": ["string"],
  "nextActions": ["string"],
  "evidenceGraph": {
    "nodes": [
      {
        "id": "string",
        "name": "string",
        "type": "string",
        "properties": {}
      }
    ],
    "edges": [
      {
        "id": "string",
        "source": "string",
        "target": "string",
        "type": "string",
        "properties": {}
      }
    ]
  },
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      question,
      sessionId,
      specialistResults,
      compactResults,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.2,
        max_tokens: 4096,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The manager agent could not generate a final answer.",
    executiveSummary: "",
    specialistSummary: [],
    keyFindings: [],
    riskLevel: "unknown",
    recommendations: [],
    nextActions: [],
    evidenceGraph: {
      nodes: [],
      edges: [],
    },
    confidence: "low",
  };
}

function normalizeEvidenceGraph(graph) {
  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];
  const edges = Array.isArray(graph?.edges) ? graph.edges : [];

  const normalizedNodes = nodes
    .filter((n) => n && (n.id || n.name))
    .map((n, index) => ({
      id: String(n.id || `node_${index + 1}`),
      name: String(n.name || n.id || `Node ${index + 1}`),
      type: String(n.type || n.label || "Entity"),
      properties:
        n.properties && typeof n.properties === "object"
          ? n.properties
          : {},
    }));

  const normalizedEdges = edges
    .filter((e) => e && (e.source || e.from) && (e.target || e.to))
    .map((e, index) => ({
      id: String(e.id || `edge_${index + 1}`),
      source: String(e.source || e.from),
      target: String(e.target || e.to),
      type: String(e.type || e.relationship || "RELATED_TO"),
      properties:
        e.properties && typeof e.properties === "object"
          ? e.properties
          : {},
    }));

  return {
    nodes: normalizedNodes,
    edges: normalizedEdges,
  };
}

let context = {};
try {
  context = $("Build Manager LLM Payload").first().json;
} catch (e) {
  context = {};
}

return [
  {
    json: {
      agent: "manager_agent",
      domain: "Supply Chain Manager",
      status: "completed",
      question: context.question || "",
      sessionId: context.sessionId || "default-session",
      answer: parsed.answer || "",
      executiveSummary: parsed.executiveSummary || "",
      specialistSummary: parsed.specialistSummary || [],
      keyFindings: parsed.keyFindings || [],
      riskLevel: parsed.riskLevel || "unknown",
      recommendations: parsed.recommendations || [],
      nextActions: parsed.nextActions || [],
      confidence: parsed.confidence || "medium",
      evidenceGraph: normalizeEvidenceGraph(parsed.evidenceGraph),
      specialistResults: context.specialistResults || [],
      rawLlmOutput: parsed,
    },
  },
];
